const nextConfig = {
  experimental: {
    serverActions: {
      bodySizeLimit: '1mb',
    },
  },
};

export default nextConfig;

import fs from 'node:fs/promises';
import path from 'node:path';
import { nanoid } from 'nanoid';

const DATA_DIR = path.join(process.cwd(), 'data');
const DATA_FILE = path.join(DATA_DIR, 'books.json');

async function ensureFile() {
  await fs.mkdir(DATA_DIR, { recursive: true });
  try {
    await fs.access(DATA_FILE);
  } catch {
    await fs.writeFile(DATA_FILE, '[]', 'utf8');
  }
}

export async function readAll() {
  await ensureFile();
  const raw = await fs.readFile(DATA_FILE, 'utf8');
  try {
    const parsed = JSON.parse(raw);
    return Array.isArray(parsed) ? parsed : [];
  } catch {
    return [];
  }
}

async function writeAll(books) {
  await ensureFile();
  await fs.writeFile(DATA_FILE, JSON.stringify(books, null, 2), 'utf8');
}

export async function getById(id) {
  const books = await readAll();
  return books.find((b) => b.id === id) ?? null;
}

export async function addBook({ title, author, notes }) {
  const books = await readAll();
  const book = {
    id: nanoid(10),
    title: title.trim(),
    author: author.trim(),
    notes: (notes ?? '').trim(),
    status: 'reading',
    createdAt: new Date().toISOString(),
    finishedAt: null,
  };
  books.push(book);
  await writeAll(books);
  return book;
}

export async function markFinished(id) {
  const books = await readAll();
  const book = books.find((b) => b.id === id);
  if (!book) return null;
  book.status = 'finished';
  book.finishedAt = new Date().toISOString();
  await writeAll(books);
  return book;
}

export async function updateNotes(id, notes) {
  const books = await readAll();
  const book = books.find((b) => b.id === id);
  if (!book) return null;
  book.notes = (notes ?? '').trim();
  await writeAll(books);
  return book;
}

'use server';

import { revalidatePath } from 'next/cache';
import { redirect } from 'next/navigation';
import { addBook, markFinished, updateNotes } from '../lib/books.js';

export async function addBookAction(formData) {
  const title = formData.get('title');
  const author = formData.get('author');
  const notes = formData.get('notes');

  if (!title || !author) {
    return;
  }

  await addBook({ title, author, notes });
  revalidatePath('/');
}

export async function markFinishedAction(formData) {
  const id = formData.get('id');
  if (!id) return;
  await markFinished(id);
  revalidatePath('/');
  revalidatePath(`/books/${id}`);
}

export async function updateNotesAction(formData) {
  const id = formData.get('id');
  const notes = formData.get('notes');
  if (!id) return;
  await updateNotes(id, notes);
  revalidatePath(`/books/${id}`);
  redirect(`/books/${id}`);
}

:root {
  color-scheme: light dark;
  --fg: #1a1a1a;
  --bg: #fafafa;
  --muted: #666;
  --border: #ddd;
  --accent: #2563eb;
}

@media (prefers-color-scheme: dark) {
  :root {
    --fg: #f0f0f0;
    --bg: #1a1a1a;
    --muted: #999;
    --border: #333;
    --accent: #60a5fa;
  }
}

* {
  box-sizing: border-box;
}

body {
  margin: 0;
  font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
  color: var(--fg);
  background: var(--bg);
  line-height: 1.5;
}

main {
  max-width: 720px;
  margin: 0 auto;
  padding: 2rem 1rem;
}

h1 {
  margin: 0 0 1.5rem;
  font-size: 1.75rem;
}

h2 {
  margin: 2rem 0 0.75rem;
  font-size: 1.15rem;
  color: var(--muted);
  text-transform: uppercase;
  letter-spacing: 0.05em;
}

ul.books {
  list-style: none;
  padding: 0;
  margin: 0 0 1rem;
}

ul.books li {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 1rem;
  padding: 0.75rem 0;
  border-bottom: 1px solid var(--border);
}

ul.books li .info {
  flex: 1;
  min-width: 0;
}

ul.books li a {
  color: var(--fg);
  text-decoration: none;
  font-weight: 500;
}

ul.books li a:hover {
  text-decoration: underline;
}

ul.books li .author {
  color: var(--muted);
  font-size: 0.9rem;
}

form.add, form.notes {
  display: grid;
  gap: 0.75rem;
  padding: 1rem;
  background: color-mix(in srgb, var(--bg), var(--fg) 4%);
  border: 1px solid var(--border);
  border-radius: 6px;
  margin: 1rem 0;
}

label {
  display: grid;
  gap: 0.25rem;
  font-size: 0.85rem;
  color: var(--muted);
}

input[type="text"], textarea {
  width: 100%;
  padding: 0.5rem;
  font: inherit;
  color: var(--fg);
  background: var(--bg);
  border: 1px solid var(--border);
  border-radius: 4px;
}

textarea {
  min-height: 6rem;
  resize: vertical;
}

button {
  padding: 0.5rem 1rem;
  font: inherit;
  color: white;
  background: var(--accent);
  border: none;
  border-radius: 4px;
  cursor: pointer;
}

button:hover {
  opacity: 0.9;
}

button.secondary {
  background: transparent;
  color: var(--muted);
  border: 1px solid var(--border);
}

.empty {
  color: var(--muted);
  font-style: italic;
  padding: 0.75rem 0;
}

.back {
  display: inline-block;
  margin-bottom: 1rem;
  color: var(--muted);
  font-size: 0.9rem;
}

.book-detail h1 {
  margin-bottom: 0.25rem;
}

.book-detail .author {
  color: var(--muted);
  margin-bottom: 1.5rem;
}

.book-detail .status {
  display: inline-block;
  padding: 0.15rem 0.5rem;
  border-radius: 999px;
  background: color-mix(in srgb, var(--accent) 20%, transparent);
  color: var(--accent);
  font-size: 0.8rem;
  margin-bottom: 1.5rem;
}

.book-detail .notes-content {
  white-space: pre-wrap;
  padding: 1rem;
  background: color-mix(in srgb, var(--bg), var(--fg) 4%);
  border: 1px solid var(--border);
  border-radius: 6px;
  margin-bottom: 1.5rem;
}

.share-link {
  font-size: 0.85rem;
  color: var(--muted);
  word-break: break-all;
}

import './globals.css';

export const metadata = {
  title: 'Reading Tracker',
  description: 'Keep track of what you are reading',
};

export default function RootLayout({ children }) {
  return (
    <html lang="en">
      <body>{children}</body>
    </html>
  );
}

import Link from 'next/link';
import { readAll } from '../lib/books.js';
import { addBookAction, markFinishedAction } from './actions.js';

export const dynamic = 'force-dynamic';

export default async function HomePage() {
  const books = await readAll();
  const reading = books.filter((b) => b.status !== 'finished');
  const finished = books.filter((b) => b.status === 'finished');

  return (
    <main>
      <h1>Reading Tracker</h1>

      <h2>Add a book</h2>
      <form className="add" action={addBookAction}>
        <label>
          Title
          <input type="text" name="title" required />
        </label>
        <label>
          Author
          <input type="text" name="author" required />
        </label>
        <label>
          Notes (optional)
          <textarea name="notes" rows={3} />
        </label>
        <button type="submit">Add to reading list</button>
      </form>

      <h2>Currently reading ({reading.length})</h2>
      {reading.length === 0 ? (
        <p className="empty">Nothing here yet.</p>
      ) : (
        <ul className="books">
          {reading.map((book) => (
            <li key={book.id}>
              <div className="info">
                <Link href={`/books/${book.id}`}>{book.title}</Link>
                <div className="author">by {book.author}</div>
              </div>
              <form action={markFinishedAction}>
                <input type="hidden" name="id" value={book.id} />
                <button type="submit" className="secondary">Mark finished</button>
              </form>
            </li>
          ))}
        </ul>
      )}

      <h2>Finished ({finished.length})</h2>
      {finished.length === 0 ? (
        <p className="empty">No finished books yet.</p>
      ) : (
        <ul className="books">
          {finished.map((book) => (
            <li key={book.id}>
              <div className="info">
                <Link href={`/books/${book.id}`}>{book.title}</Link>
                <div className="author">by {book.author}</div>
              </div>
            </li>
          ))}
        </ul>
      )}
    </main>
  );
}

import Link from 'next/link';
import { headers } from 'next/headers';
import { notFound } from 'next/navigation';
import { getById } from '../../../lib/books.js';
import { updateNotesAction } from '../../actions.js';

export const dynamic = 'force-dynamic';

export async function generateMetadata({ params }) {
  const { id } = await params;
  const book = await getById(id);
  if (!book) return { title: 'Not found' };
  return { title: `${book.title} by ${book.author}` };
}

export default async function BookPage({ params }) {
  const { id } = await params;
  const book = await getById(id);
  if (!book) notFound();

  const headerList = await headers();
  const host = headerList.get('host') ?? 'localhost:3000';
  const proto = headerList.get('x-forwarded-proto') ?? 'http';
  const url = `${proto}://${host}/books/${book.id}`;

  const isFinished = book.status === 'finished';

  return (
    <main className="book-detail">
      <Link href="/" className="back">&larr; Back to all books</Link>
      <h1>{book.title}</h1>
      <div className="author">by {book.author}</div>
      <div className="status">{isFinished ? 'Finished' : 'Reading'}</div>

      <h2>Notes</h2>
      {book.notes ? (
        <div className="notes-content">{book.notes}</div>
      ) : (
        <p className="empty">No notes yet.</p>
      )}

      <form className="notes" action={updateNotesAction}>
        <input type="hidden" name="id" value={book.id} />
        <label>
          Edit notes
          <textarea name="notes" defaultValue={book.notes} rows={6} />
        </label>
        <button type="submit">Save notes</button>
      </form>

      <h2>Share</h2>
      <p className="share-link">{url}</p>
    </main>
  );
}

import { describe, it, expect, beforeEach } from 'vitest';
import fs from 'node:fs/promises';
import path from 'node:path';
import { tmpdir } from 'node:os';

const tmp = await fs.mkdtemp(path.join(tmpdir(), 'books-test-'));
process.chdir(tmp);
await fs.writeFile(path.join(tmp, 'data', '.gitkeep'), '');

const { readAll, addBook, getById, markFinished, updateNotes } = await import('../lib/books.js');

describe('books storage', () => {
  beforeEach(async () => {
    await fs.writeFile(path.join(tmp, 'data', 'books.json'), '[]', 'utf8');
  });

  it('starts empty', async () => {
    expect(await readAll()).toEqual([]);
  });

  it('adds a book with status reading and an id', async () => {
    const book = await addBook({ title: 'Dune', author: 'Frank Herbert', notes: 'great' });
    expect(book.id).toBeTruthy();
    expect(book.title).toBe('Dune');
    expect(book.author).toBe('Frank Herbert');
    expect(book.notes).toBe('great');
    expect(book.status).toBe('reading');
    expect(book.finishedAt).toBeNull();
  });

  it('persists across reads', async () => {
    await addBook({ title: 'A', author: 'B' });
    const all = await readAll();
    expect(all).toHaveLength(1);
    expect(all[0].title).toBe('A');
  });

  it('gets a book by id', async () => {
    const book = await addBook({ title: 'A', author: 'B' });
    expect(await getById(book.id)).toMatchObject({ title: 'A', author: 'B' });
    expect(await getById('nope')).toBeNull();
  });

  it('marks a book finished', async () => {
    const book = await addBook({ title: 'A', author: 'B' });
    const updated = await markFinished(book.id);
    expect(updated.status).toBe('finished');
    expect(updated.finishedAt).toBeTruthy();
    const refetched = await getById(book.id);
    expect(refetched.status).toBe('finished');
  });

  it('updates notes', async () => {
    const book = await addBook({ title: 'A', author: 'B', notes: 'old' });
    const updated = await updateNotes(book.id, 'new thoughts');
    expect(updated.notes).toBe('new thoughts');
  });

  it('trims whitespace from fields', async () => {
    const book = await addBook({ title: '  A  ', author: ' B ', notes: ' n ' });
    expect(book.title).toBe('A');
    expect(book.author).toBe('B');
    expect(book.notes).toBe('n');
  });
});

